font_css:
:root { --display: "Space Grotesk", "Noto Sans JP", sans-serif; --text: "Instrument Sans", "Noto Sans JP", system-ui, sans-serif; }
html[lang="ja"] body { letter-spacing: .02em; line-height: 1.85; }
html[lang="ja"] h1 { letter-spacing: -.02em; font-weight: 700; }
html[lang="ja"] .feature-title, html[lang="ja"] h2, html[lang="ja"] h3 { letter-spacing: 0; }
html[lang="ja"] .feature-title { word-break: keep-all; }
